      expect(inputFrameRow, greaterThan(0));
      final aboutRow = lines.indexWhere((l) => l.contains('zero-knowledge'));
      expect(aboutRow, greaterThan(0));
      expect(aboutRow, lessThan(inputFrameRow));

      await harness.runSlashCommand('/exit');
