    test('zero wrapped rows with overlong tool output at '
        '$columns x$rowsCount', () async {
      final tempHome = Directory.systemTemp.createTempSync('fa_tui_467_wrap_');
      final ascii520 = 'gh issue create --title "${'x' * 500}"';
