  /// rows anywhere, no board-snapshot residue, status pinned to the bottom.
  for (final (columns, rowsCount) in [(100, 40), (80, 24)]) {
    test('zero wrapped rows with overlong tool output at '
        '$columns x$rowsCount', () async {
