      final rule = '─' * columns;
      final rules = <int>[
        for (var i = 0; i < gridA.length; i++)
          if (gridA[i].trim() == rule) i,
      ];
      expect(rules.length, greaterThanOrEqualTo(2), reason: 'input frame');
      final region = gridA
          .sublist(rules[rules.length - 2] + 1, rules.last)
          .map((l) => l.trimRight())
          .toList();
