      final dapRows = harness.screenLines
          .where((line) => line.contains('/dap'))
          .toList();
      expect(dapRows, hasLength(1), reason: harness.screenText);
      harness.sendEscape();
      await Future<void>.delayed(const Duration(milliseconds: 200));
      harness.sendCtrlC();
